extern "C" {
void k_preparation(
        const qp_t* abcd_inp,
        const rys_t* rtwt_rys_inp,
        int n,
        hls::stream<D_WIDTH( xyz_derived_pt::bit_width ) >& xyz_derived_stream_out,
        hls::stream<D_WIDTH( rys_wt_pt::bit_width ) >& rys_wt_stream_out,
        hls::stream<D_WIDTH( tb_b_pt::bit_width ) >& tb_b_stream_out,
