        preparation( abcd, rtwt_rys, xyz_derived, tb_b, tb_c );

        rys_wt_pt rys_wt;
        rys_wt.copy_from( rtwt_rys.wt );

        xyz_derived_stream_out.write( xyz_derived );
        rys_wt_stream_out.write( rys_wt );
        tb_b_stream_out.write( tb_b );
        tb_c_stream_out.write( tb_c );
    }
}
