// Arbitrary-precision unsigned integer
template<int W>
class ap_uint {
public:
    uint64_t val;

    ap_uint() : val(0) {}
    ap_uint(unsigned int v) : val(v) {}
    ap_uint(unsigned long v) : val(v) {}
    ap_uint(unsigned long long v) : val(v) {}
    ap_uint(int v) : val(v) {}
    ap_uint(short v) : val(v) {}

