        return ap_range_ref<W>(this, hi, lo);
    }

    template<int W2>
    ap_uint<W2> range(int hi, int lo) const {
        ap_uint<W2> result;
        uint64_t mask = (W2 >= 64) ? ~0ULL : ((1ULL << W2) - 1);
        result.val = (val >> lo) & mask;
        return result;
    }

    ap_uint operator+(const ap_uint& other) const { return ap_uint(val + other.val); }
    ap_uint operator-(const ap_uint& other) const { return ap_uint(val - other.val); }
